package com.cineflow.bug.config; import io.swagger.v3.oas.models.*; import io.swagger.v3.oas.models.info.Info; import io.swagger.v3.oas.models.security.*; import io.swagger.v3.oas.models.servers.Server; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; @Configuration public class OpenApiConfig { @Bean OpenAPI api(@Value("${OPENAPI_SERVER_URL:/bug-management}")String url){return new OpenAPI().addServersItem(new Server().url(url).description("Bug Management API Gateway")).info(new Info().title("Bug Management API").version("v1").description("Bug, QC frame, annotation, reference and attachment management")).addSecurityItem(new SecurityRequirement().addList("bearerAuth")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));} }
